CREATE DATABASE Customer_Behaviour;
use Customer_Behaviour;
select * from mytable;

#Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) from mytable
group by gender;

#Q2. Which customers used a discount but still spent more than the average purchase amount? 
select customer_id,purchase_amount from mytable
where discount_applied="yes" and purchase_amount>=(select avg(purchase_amount) from mytable);

#Q3. Which are the top 5 products with the highest average review rating?
select item_purchased,
		round(avg(review_rating),2) as "Average Product Rating" from mytable
group by item_purchased
order by avg(review_rating) desc
limit 5 ;

#Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select shipping_type,
		round(avg(purchase_amount),2) as "Average purchase amount" from mytable
where shipping_type in ("Express","Standard")
group by shipping_type;

#Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers
select subscription_status,
		count(customer_id) as tot_customers,
		round(avg(purchase_amount),2) as avg_spend,
        round(sum(purchase_amount),2) as tot_revenue
from mytable
group by subscription_status
order by tot_revenue,avg_spend desc;

#Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT 
    item_purchased,
    COUNT(*) AS total_orders,
    SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) AS discounted_orders,
    ROUND(SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS discount_rate_percentage
FROM mytable
GROUP BY item_purchased
ORDER BY discount_rate_percentage DESC
LIMIT 5;

#Q7. Segment customers into New, Returning, and Loyal based on their total 
# number of previous purchases, and show the count of each segment. 
SELECT 
    CASE 
        WHEN previous_purchases BETWEEN 1 AND 2 THEN 'New Customer'
        WHEN previous_purchases BETWEEN 3 AND 8 THEN 'Returning Customer'
        ELSE 'Loyal Customer'
    END AS customer_segment,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS average_spend
FROM mytable
GROUP BY customer_segment
ORDER BY total_customers DESC;

#Q8. What are the top 3 most purchased products within each category? 
with item_count as(
	select 
		item_purchased,category, 
		count(customer_id) as tot_orders,
		row_number() over(partition by category order by count(customer_id) desc) as item_rank 
	from mytable
	group by item_purchased, category)
select item_rank,category,item_purchased,tot_orders
from item_count
where item_rank<=3;
        
#Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe
select subscription_status,count(customer_id) as repeat_buyers from mytable
where previous_purchases>5
group by subscription_status;

#Q10. What is the revenue contribution of each age group? 
select 
	age_group,
	sum(purchase_amount) as tot_revenue from mytable
group by age_group
order by tot_revenue desc;



